     last=Apply(request,engine,context,document,summary);if(factoryCapture!=null){factoryCapture.Dispose();factoryCapture=null;}individual.Add(new Dictionary<string,object>{{"action_id",action["action_id"]},{"result",last},{"direct_summary",summary},{"direct_summary_utf8_sha256",document["native_summary_utf8_sha256"]},{"timings_ms",new Dictionary<string,object>{{"read_target",readMs},{"current_summary_and_plan",summaryMs},{"prepare_apply_verify_and_flush",actionClock.Elapsed.TotalMilliseconds}}}});
     foreach(object report in(IEnumerable)last["actions"]){var row=Map(report);if(row.ContainsKey("flush"))flushReports.Add(report);else reports.Add(report);}
     if(!Object.Equals(last["ok"],true)){result["failed_action_id"]=action["action_id"];result["error"]=last.ContainsKey("error")?last["error"]:"Native action did not complete.";break;}completed++;result["completed_action_count"]=completed;
     if(factoryBatch!=null&&i==factoryEnd){phase="direct-factory-batch-finalize";result["batch_finalization_action_id"]=action["action_id"];try{factoryBatches.Add(factoryBatch.Complete());}catch{result["native_batch_finalization_failed"]=true;result["failed_action_id"]=action["action_id"];throw;}finally{factoryBatch.Dispose();factoryBatch=null;}result.Remove("batch_finalization_action_id");}
    }
    result["ok"]=completed==actions.Count;result["completed_action_count"]=completed;result["requested_action_count"]=actions.Count;
    if(last!=null){foreach(string key in new[]{"status","root_save","permit_status","explicit_child_flushes_requested","root_save_requested","persistence_scope","native_configuration_check_completed","native_configuration_check_passed","native_configuration_check_verified","native_configuration_check_return_int32","error_count","warning_count","error_warning_counts_known","headless","original_worker_ui_preserved"})if(last.ContainsKey(key))result[key]=last[key];}
   }catch(Exception error){result["error"]=error.GetType().Name+": "+error.Message;result["managed_stack"]=error.StackTrace;result["comparison_evidence"]=NativeEngineeringComparisonEvidence.Metadata(error);}finally{if(factoryCapture!=null){factoryCapture.Dispose();factoryCapture=null;}if(factoryBatch!=null){result["incomplete_factory_batch_created_count"]=factoryBatch.appliedCount;result["incomplete_factory_batch_count_is_lower_bound"]=true;factoryBatch.Dispose();}result["completed_action_count"]=completed;}
